SELECT 'TIMING' AS src, symbol, interval_code, candle_open_time, observed_at, stage, started_at, finished_at, elapsed_ms, outcome, thread_name FROM crypto_ai.fix129_stage_timing WHERE started_at BETWEEN '2026-10-11 20:59:30' AND '2026-10-11 21:00:30' OR started_at BETWEEN '2026-10-11 22:42:30' AND '2026-10-11 22:44:00' OR started_at BETWEEN '2026-10-12 03:29:30' AND '2026-10-12 03:30:30' OR started_at BETWEEN '2026-10-12 07:14:30' AND '2026-10-12 07:16:00' OR started_at BETWEEN '2026-10-12 10:04:30' AND '2026-10-12 10:05:40' UNION ALL SELECT 'FIX124', symbol, interval_code, candle_open_time, observed_at, outcome, NULL, NULL, attempts, LEFT(error_message, 200), NULL FROM crypto_ai.fix124_protection_incident WHERE observed_at BETWEEN '2026-10-11 20:50:00' AND '2026-10-12 10:10:00' ORDER BY 7 LIMIT 200